package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.NumberIsTooSmallException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BrentSolver.solve method.
 * Focuses on maximizing branch and line coverage.
 */
public class BrentSolver_solve_TriageGen1Test {

    private BrentSolver solver;

    @Mock
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        solver = new BrentSolver();
    }

    /**
     * Test case where the initial guess is already the root.
     * Covers: if (Math.abs(yInitial) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_InitialGuessIsRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // Assuming functionValueAccuracy is small, e.g., 1e-14
        when(function.value(initial)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);

        assertEquals(initial, result, 1e-14);
    }

    /**
     * Test case where the minimum endpoint is the root.
     * Covers: if (Math.abs(yMin) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MinEndpointIsRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);

        assertEquals(min, result, 1e-14);
    }

    /**
     * Test case where the initial guess and min bracket the root.
     * Covers: if (yInitial * yMin < 0)
     */
    @Test
    public void testSolve_InitialAndMinBracketRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // yInitial (1.0) * yMin (-1.0) < 0
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(-1.0);
        // To avoid infinite recursion in a unit test for this specific logic branch, 
        // we simulate a function that is easy for the underlying Brent algorithm to solve
        // once the interval is reduced. 
        // For simplicity in this triage, we use a real function for the second call.
        UnivariateRealFunction realFunc = x -> x - 1.0; 

        double result = solver.solve(realFunc, min, max, initial);
        assertEquals(1.0, result, 1e-10);
    }

    /**
     * Test case where the maximum endpoint is the root.
     * Covers: if (Math.abs(yMax) <= functionValueAccuracy)
     */
    @Test
    public void testSolve_MaxEndpointIsRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(0.0);

        double result = solver.solve(function, min, max, initial);

        assertEquals(max, result, 1e-14);
    }

    /**
     * Test case where the initial guess and max bracket the root.
     * Covers: if (yInitial * yMax < 0)
     */
    @Test
    public void testSolve_InitialAndMaxBracketRoot() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // yInitial (1.0) * yMax (-1.0) < 0
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(-1.0);

        UnivariateRealFunction realFunc = x -> x - 3.0;

        double result = solver.solve(realFunc, min, max, initial);
        assertEquals(3.0, result, 1e-10);
    }

    /**
     * Test case where min and max do not bracket the root.
     * Covers: if (yMin * yMax > 0) -> throws IllegalArgumentException
     */
    @Test
    public void testSolve_NoBracketingThrowsException() throws Exception {
        double initial = 2.0;
        double min = 0.0;
        double max = 5.0;
        // yInitial (1.0), yMin (1.0), yMax (1.0) -> no sign change
        when(function.value(initial)).thenReturn(1.0);
        when(function.value(min)).thenReturn(1.0);
        when(function.value(max)).thenReturn(1.0);

        assertThrows(IllegalArgumentException.class, () -> {
            solver.solve(function, min, max, initial);
        });
    }

    /**
     * Test case for the full Brent algorithm path.
     * Covers: final return statement (full Brent algorithm)
     */
    @Test
    public void testSolve_FullBrentAlgorithm() throws Exception {
        // Function f(x) = x^2 - 4. Roots at 2 and -2.
        UnivariateRealFunction f = x -> x * x - 4.0;
        double min = 0.0;
        double max = 5.0;
        double initial = 3.0;
        // yMin = -4, yMax = 21, yInitial = 5. 
        // yMin * yMax < 0, so it enters the full algorithm.

        double result = solver.solve(f, min, max, initial);
        assertEquals(2.0, result, 1e-10);
    }

    /**
     * Test case for invalid sequence (min > max).
     * Covers: verifySequence(min, initial, max)
     */
    @Test
    public void testSolve_InvalidSequence() {
        // Depending on implementation of verifySequence, it might throw IllegalArgumentException or NumberIsTooSmallException
        assertThrows(IllegalArgumentException.class, () -> {
            solver.solve(function, 5.0, 0.0, 2.0);
        });
    }
}
